{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h2",
        "intro_text",
        "context_h3",
        "context_list",
        "meals_h2",
        "day1_card",
        "day2_card",
        "day3_card",
        "day4_card",
        "day5_card",
        "day6_card",
        "day7_card",
        "resources_h3",
        "explore_recipes_button",
        "download_list_button"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Vegetarian Meal Plan: October 7-13",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This 7-day vegetarian meal plan provides varied, healthy meals for a single adult, targeting 1800-2000 calories daily. Each meal is designed for approximately 30 minutes of active cooking time."
      },
      "children": []
    },
    "context_h3": {
      "type": "Text",
      "props": {
        "text": "Plan Context",
        "variant": "h3"
      },
      "children": []
    },
    "context_list": {
      "type": "List",
      "props": {},
      "children": [
        "context_item1",
        "context_item2",
        "context_item3"
      ]
    },
    "context_item1": {
      "type": "Text",
      "props": {
        "text": "Calorie estimates are approximate and can vary based on specific ingredients and portion sizes."
      },
      "children": []
    },
    "context_item2": {
      "type": "Text",
      "props": {
        "text": "\"Active cooking time\" refers to hands-on prep and cooking, not passive simmering or baking."
      },
      "children": []
    },
    "context_item3": {
      "type": "Text",
      "props": {
        "text": "Recipes assume basic pantry staples are available."
      },
      "children": []
    },
    "meals_h2": {
      "type": "Text",
      "props": {
        "text": "Quick & Healthy Vegetarian Meals",
        "variant": "h2"
      },
      "children": []
    },
    "day1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day1_header_stack",
        "day1_morning_text",
        "day1_afternoon_text",
        "day1_dinner_text"
      ]
    },
    "day1_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "day1_icon",
        "day1_title_h3"
      ]
    },
    "day1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000851_01_1_cup-hot.svg"
      },
      "children": []
    },
    "day1_title_h3": {
      "type": "Text",
      "props": {
        "text": "Day 1: Monday, October 7",
        "variant": "h3"
      },
      "children": []
    },
    "day1_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Berry Nut Oatmeal - Rolled oats cooked with water/milk, topped with mixed berries, a handful of walnuts, and a drizzle of maple syrup."
      },
      "children": []
    },
    "day1_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Chickpea Salad Sandwich - Mashed chickpeas mixed with celery, vegan mayo, and herbs, served on whole-wheat bread with lettuce and tomato."
      },
      "children": []
    },
    "day1_dinner_text": {
      "type": "Text",
      "props": {
        "text": "Dinner: Quick Lentil Pasta - Whole-wheat pasta with a store-bought marinara sauce, sautéed spinach, and a sprinkle of nutritional yeast."
      },
      "children": []
    },
    "day2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day2_header_stack",
        "day2_morning_text",
        "day2_afternoon_text",
        "day2_dinner_text"
      ]
    },
    "day2_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "day2_icon",
        "day2_title_h3"
      ]
    },
    "day2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000851_01_1_cup-hot.svg"
      },
      "children": []
    },
    "day2_title_h3": {
      "type": "Text",
      "props": {
        "text": "Day 2: Tuesday, October 8",
        "variant": "h3"
      },
      "children": []
    },
    "day2_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Yogurt & Granola Parfait - Layers of Greek yogurt, granola, and fresh fruit (e.g., banana, apple slices)."
      },
      "children": []
    },
    "day2_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Leftover Lentil Pasta - Reheat and enjoy the previous night's pasta."
      },
      "children": []
    },
    "day2_dinner_text": {
      "type": "Text",
      "props": {
        "text": "Dinner: Black Bean Burgers - Store-bought black bean patties cooked and served on whole-wheat buns with lettuce, tomato, and a side salad."
      },
      "children": []
    },
    "day3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day3_title_h3",
        "day3_morning_text",
        "day3_afternoon_text",
        "day3_dinner_text"
      ]
    },
    "day3_title_h3": {
      "type": "Text",
      "props": {
        "text": "Day 3: Wednesday, October 9",
        "variant": "h3"
      },
      "children": []
    },
    "day3_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Tofu Scramble with Toast - Crumbled tofu sautéed with turmeric, nutritional yeast, and veggies (bell peppers, onions), served with whole-wheat toast."
      },
      "children": []
    },
    "day3_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Quinoa & Feta Salad - Cooked quinoa mixed with cucumber, cherry tomatoes, Kalamata olives, feta cheese, and a lemon-herb vinaigrette."
      },
      "children": []
    },
    "day3_dinner_text": {
      "type": "Text",
      "props": {
        "text": "Dinner: Speedy Veggie Stir-fry - Quick-cooking vegetables (broccoli, carrots, snap peas) stir-fried with tofu or tempeh and a pre-made stir-fry sauce, served over brown rice."
      },
      "children": []
    },
    "day4_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day4_header_stack",
        "day4_morning_text",
        "day4_afternoon_text",
        "day4_dinner_text"
      ]
    },
    "day4_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "day4_icon",
        "day4_title_h3"
      ]
    },
    "day4_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000851_01_1_cup-hot.svg"
      },
      "children": []
    },
    "day4_title_h3": {
      "type": "Text",
      "props": {
        "text": "Day 4: Thursday, October 10",
        "variant": "h3"
      },
      "children": []
    },
    "day4_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Green Smoothie - Blend spinach, banana, plant-based milk, a scoop of protein powder, and a tablespoon of almond butter."
      },
      "children": []
    },
    "day4_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Leftover Veggie Stir-fry - Reheat and enjoy the previous night's stir-fry."
      },
      "children": []
    },
    "day4_dinner_text": {
      "type": "Text",
      "props": {
        "text": "Dinner: Sheet Pan Fajita Veggies - Bell peppers, onions, and mushrooms tossed with fajita seasoning and roasted until tender, served with warm tortillas and refried beans."
      },
      "children": []
    },
    "day5_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day5_header_stack",
        "day5_morning_text",
        "day5_afternoon_text",
        "day5_dinner_text"
      ]
    },
    "day5_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "day5_icon",
        "day5_title_h3"
      ]
    },
    "day5_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000851_01_1_cup-hot.svg"
      },
      "children": []
    },
    "day5_title_h3": {
      "type": "Text",
      "props": {
        "text": "Day 5: Friday, October 11",
        "variant": "h3"
      },
      "children": []
    },
    "day5_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Avocado Toast - Smashed avocado on whole-wheat toast, seasoned with everything bagel seasoning or red pepper flakes."
      },
      "children": []
    },
    "day5_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: White Bean & Kale Soup - Canned cannellini beans, vegetable broth, sautéed kale, and diced tomatoes, simmered briefly."
      },
      "children": []
    },
    "day5_dinner_text": {
      "type": "Text",
      "props": {
        "text": "Dinner: Quick Coconut Curry - Canned full-fat coconut milk simmered with curry paste, chickpeas, and quick-cooking vegetables (e.g., frozen mixed veggies, spinach), served with basmati rice."
      },
      "children": []
    },
    "day6_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day6_header_stack",
        "day6_morning_text",
        "day6_afternoon_text",
        "day6_dinner_text"
      ]
    },
    "day6_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "day6_icon",
        "day6_title_h3"
      ]
    },
    "day6_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000851_01_1_cup-hot.svg"
      },
      "children": []
    },
    "day6_title_h3": {
      "type": "Text",
      "props": {
        "text": "Day 6: Saturday, October 12",
        "variant": "h3"
      },
      "children": []
    },
    "day6_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Vegan Pancakes - Prepare a quick batch of vegan pancakes from a mix or scratch, topped with fresh fruit and maple syrup."
      },
      "children": []
    },
    "day6_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Leftover Coconut Curry - Enjoy the flavorful curry from the previous evening."
      },
      "children": []
    },
    "day6_dinner_text": {
      "type": "Text",
      "props": {
        "text": "Dinner: Mediterranean Couscous Bowls - Fluffy couscous topped with hummus, chopped cucumber, tomatoes, Kalamata olives, a sprinkle of fresh parsley, and grilled halloumi or chickpeas."
      },
      "children": []
    },
    "day7_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day7_header_stack",
        "day7_morning_text",
        "day7_afternoon_text",
        "day7_dinner_text"
      ]
    },
    "day7_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "day7_icon",
        "day7_title_h3"
      ]
    },
    "day7_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000851_01_1_cup-hot.svg"
      },
      "children": []
    },
    "day7_title_h3": {
      "type": "Text",
      "props": {
        "text": "Day 7: Sunday, October 13",
        "variant": "h3"
      },
      "children": []
    },
    "day7_morning_text": {
      "type": "Text",
      "props": {
        "text": "Morning: Breakfast Burrito - Scrambled eggs (or tofu scramble), black beans, salsa, and shredded cheese (or vegan cheese) wrapped in a whole-wheat tortilla."
      },
      "children": []
    },
    "day7_afternoon_text": {
      "type": "Text",
      "props": {
        "text": "Afternoon: Large Garden Salad - Mixed greens with a variety of chopped vegetables, sunflower seeds, and a protein source like grilled tempeh or a hard-boiled egg."
      },
      "children": []
    },
    "day7_dinner_text": {
      "type": "Text",
      "props": {
        "text": "Dinner: Hearty Vegetarian Chili - Canned kidney beans, black beans, diced tomatoes, corn, and chili spices simmered for 20-30 minutes, served with a dollop of Greek yogurt or avocado."
      },
      "children": []
    },
    "resources_h3": {
      "type": "Text",
      "props": {
        "text": "Meal Prep Resources",
        "variant": "h3"
      },
      "children": []
    },
    "explore_recipes_button": {
      "type": "Button",
      "props": {
        "label": "Explore Recipes"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.loveandlemons.com/vegetarian-recipes/"
          }
        }
      }
    },
    "download_list_button": {
      "type": "Button",
      "props": {
        "label": "Download List"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.template.net/editable/10639/grocery-list-template-word"
          }
        }
      }
    }
  }
}
